sp_widget.client_script:
api.controller = function($scope, $location, $window) {
  /* =========================================================================
     CLIENT CONTROLLER
     ========================================================================= */
  var c = this;

  c.isOpen = false;
  c.activeTab = 'all';

  // Toggle notification popup panel
  c.togglePanel = function() {
    c.isOpen = !c.isOpen;
  };

  // Recalculate badge total dynamically based on unread items
  c.updateTotalCount = function() {
    var unreadAnn = c.data.announcements.filter(function(i) { return !i.read; }).length;
    var unreadReq = c.data.requests.filter(function(i) { return !i.read; }).length;
    c.data.totalCount = unreadAnn + unreadReq;
  };

  // Mark all notifications as read
  c.markAllRead = function() {
    c.data.announcements.forEach(function(item) { item.read = true; });
    c.data.requests.forEach(function(item) { item.read = true; });
    c.updateTotalCount();
  };

  // Handle clicking an Announcement item
  c.openAnnouncement = function(item) {
    item.read = true;
    c.updateTotalCount();
    c.isOpen = false;

    if (item.target_url) {
      $window.open(item.target_url, '_blank');
    }
  };

  // Handle clicking a Request item
  c.openRequest = function(item) {
    item.read = true;
    c.updateTotalCount();
    c.isOpen = false;

    // Navigate to ticket details page in Service Portal
    $location.search({
      id: 'ticket',
      table: item.table,
      sys_id: item.sys_id
    });
  };
};

sp_widget.css:
/*
===============================================================================
NOTIFICATION BELL WIDGET — SPAR Futuristic Edition
Paste into the Notification Bell widget's CSS field
Matches the Light Glass / SPAR brand palette ($brand-primary, $brand-success, $brand-danger)
===============================================================================
*/

/* Wrapper */
.notif-bell-wrapper {
  position: relative;
  display: inline-block;
}

/* Bell Button */
.notif-bell {
  position: relative;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid #E2E8F0;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: transform 280ms cubic-bezier(0.34, 1.56, 0.64, 1),
              box-shadow 280ms ease,
              border-color 280ms ease,
              background-color 280ms ease;
}

.notif-bell:hover {
  background: #FFFFFF;
  border-color: #CBD5E1;
  transform: translateY(-2px);
  box-shadow: 0 8px 18px -4px rgba(15, 23, 42, 0.12);
}

.notif-bell i {
  font-size: 1.1rem;
  color: $brand-primary !important;
  transition: all 0.22s ease;
}

.notif-bell-wrapper.open .notif-bell {
  background: #FFFFFF;
  border-color: $brand-primary;
  box-shadow: 0 0 0 3px rgba(0, 122, 51, 0.15);
}

/* Shake animation on new notifications / hover */
@keyframes bellShake {
  0%, 100% { transform: rotate(0deg); }
  20%       { transform: rotate(-15deg); }
  40%       { transform: rotate(15deg); }
  60%       { transform: rotate(-10deg); }
  80%       { transform: rotate(10deg); }
}

.notif-bell:hover i {
  animation: bellShake 0.5s ease;
  color: $brand-success !important;
}

/* Badge */
.notif-badge {
  position: absolute;
  top: -3px;
  right: -3px;
  background: linear-gradient(135deg, $brand-primary 0%, $brand-danger 100%);
  color: #FFFFFF !important;
  font-size: 0.65rem;
  font-weight: 800;
  min-width: 18px;
  height: 18px;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
  border: 2px solid #FFFFFF;
  box-shadow: 0 2px 6px rgba(227, 6, 19, 0.3);
  animation: badgePop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes badgePop {
  from { transform: scale(0); }
  to   { transform: scale(1); }
}

/* Panel */
.notif-panel {
  position: absolute;
  top: calc(100% + 12px);
  right: 0;
  width: 360px;
  background: rgba(255, 255, 255, 0.98);
  backdrop-filter: blur(12px);
  border: 1px solid #E2E8F0;
  border-radius: 14px;
  box-shadow: 0 16px 40px -8px rgba(15, 23, 42, 0.18);
  z-index: 9999;
  overflow: hidden;
  animation: panelSlideIn 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.notif-panel::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, $brand-primary 0%, $brand-success 100%);
}

@keyframes panelSlideIn {
  from { opacity: 0; transform: translateY(-10px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Panel Header */
.notif-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 20px 14px;
  border-bottom: 1px solid #F1F5F9;
}

.notif-panel-title {
  font-size: 1rem !important;
  font-weight: 800 !important;
  color: #0F172A !important;
  letter-spacing: -0.01em;
  margin: 0 !important;
}

.notif-mark-read {
  font-size: 0.75rem;
  color: $brand-primary !important;
  cursor: pointer;
  font-weight: 700;
  transition: color 0.2s ease;
}

.notif-mark-read:hover {
  color: $brand-success !important;
}

/* Tabs */
.notif-tabs {
  display: flex;
  gap: 6px;
  padding: 8px 12px;
  border-bottom: 1px solid #F1F5F9;
  background: #F8FAFC;
}

.notif-tab {
  flex: 1;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 6px 8px;
  font-size: 0.75rem;
  font-weight: 700;
  color: #64748B !important;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.notif-tab:hover {
  background: #FFFFFF;
  color: #0F172A !important;
  border-color: #E2E8F0;
}

.notif-tab.active {
  background: #FFFFFF;
  color: $brand-primary !important;
  border-color: #CBD5E1;
  box-shadow: 0 2px 4px rgba(15, 23, 42, 0.04);
}

.tab-count {
  background: #E2E8F0;
  color: #475569 !important;
  border-radius: 999px;
  padding: 1px 7px;
  font-size: 0.65rem;
  font-weight: 800;
}

.notif-tab.active .tab-count {
  background: rgba(0, 122, 51, 0.12);
  color: $brand-success !important;
}

/* Notification List */
.notif-list {
  max-height: 380px;
  overflow-y: auto;
  padding: 6px 0;
}

.notif-list::-webkit-scrollbar {
  width: 5px;
}

.notif-list::-webkit-scrollbar-track {
  background: transparent;
}

.notif-list::-webkit-scrollbar-thumb {
  background: #CBD5E1;
  border-radius: 999px;
}

/* Section Label */
.notif-section-label {
  font-size: 0.68rem;
  font-weight: 800;
  color: #94A3B8 !important;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 10px 20px 4px;
}

/* Notification Item */
.notif-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 20px;
  cursor: pointer;
  transition: background-color 0.2s ease;
  position: relative;
  border-bottom: 1px solid #F8FAFC;
}

.notif-item:last-child {
  border-bottom: none;
}

.notif-item:hover {
  background: #F8FAFC;
}

/* Icon Wrap */
.notif-icon-wrap {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.announcement-icon {
  background: rgba(227, 6, 19, 0.08);
  border: 1px solid rgba(227, 6, 19, 0.20);
}

.announcement-icon i {
  color: $brand-danger !important;
  font-size: 0.875rem;
}

.request-icon {
  background: rgba(0, 122, 51, 0.08);
  border: 1px solid rgba(0, 122, 51, 0.20);
}

.request-icon i {
  color: $brand-success !important;
  font-size: 0.875rem;
}

/* Content */
.notif-content {
  flex: 1;
  min-width: 0;
}

.notif-title {
  font-size: 0.875rem !important;
  font-weight: 700 !important;
  color: #0F172A !important;
  margin: 0 0 2px !important;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.notif-desc {
  font-size: 0.775rem !important;
  color: #475569 !important;
  margin: 0 0 4px !important;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.notif-time {
  font-size: 0.70rem !important;
  color: #94A3B8 !important;
  margin: 0 !important;
  font-weight: 500;
}

/* Unread Dot */
.notif-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: $brand-danger;
  flex-shrink: 0;
  margin-top: 6px;
  box-shadow: 0 0 6px rgba(227, 6, 19, 0.4);
}

/* Empty States */
.notif-empty {
  text-align: center;
  padding: 40px 20px;
  color: #94A3B8 !important;
}

.notif-empty i {
  font-size: 2.2rem;
  margin-bottom: 8px;
  display: block;
  color: #CBD5E1 !important;
}

.notif-empty p {
  font-size: 0.875rem !important;
  color: #64748B !important;
  font-weight: 600;
}

.notif-empty-section {
  text-align: center;
  padding: 16px 20px;
  font-size: 0.8rem;
  color: #94A3B8 !important;
}

/* Panel Footer */
.notif-panel-footer {
  padding: 12px 20px;
  border-top: 1px solid #F1F5F9;
  text-align: center;
  background: #F8FAFC;
}

.notif-panel-footer a {
  font-size: 0.8rem !important;
  font-weight: 700 !important;
  color: $brand-primary !important;
  transition: color 0.2s ease;
}

.notif-panel-footer a:hover {
  color: $brand-success !important;
  text-decoration: underline !important;
}

/* Backdrop */
.notif-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9998;
  background: transparent;
}

/* Responsive */
@media (max-width: 480px) {
  .notif-panel {
    width: 300px;
    right: -60px;
  }
}

sp_widget.script:
(function() {
  /* =========================================================================
     SERVER SCRIPT: Fetch Announcements & Requests
     ========================================================================= */

  data.announcements = [];
  data.requests = [];
  var userID = gs.getUserID();

  // -------------------------------------------------------------------------
  // 1. FETCH ANNOUNCEMENTS (ServiceNow `announcement` table)
  // -------------------------------------------------------------------------
  var annGr = new GlideRecord('announcement');
  annGr.addActiveQuery();
  // Filter for currently valid display windows
  var now = new GlideDateTime().getValue();
  annGr.addNullQuery('from').addOrCondition('from', '<=', now);
  annGr.addNullQuery('to').addOrCondition('to', '>=', now);
  annGr.orderByDesc('sys_created_on');
  annGr.setLimit(10);
  annGr.query();

  while (annGr.next()) {
    data.announcements.push({
      sys_id: annGr.getUniqueValue(),
      title: annGr.getValue('title') || 'Announcement',
      short_description: annGr.getValue('summary') || annGr.getValue('name') || '',
      time: annGr.sys_created_on.getDisplayValue(),
      target_url: annGr.getValue('target_link') || '',
      read: false // Session/client tracked
    });
  }

  // -------------------------------------------------------------------------
  // 2. FETCH USER REQUESTS (Service Catalog `sc_request` table)
  // -------------------------------------------------------------------------
  var reqGr = new GlideRecord('sc_request');
  reqGr.addQuery('requested_for', userID);
  reqGr.orderByDesc('sys_updated_on');
  reqGr.setLimit(10);
  reqGr.query();

  while (reqGr.next()) {
    data.requests.push({
      sys_id: reqGr.getUniqueValue(),
      number: reqGr.getValue('number'),
      state: reqGr.getDisplayValue('state'),
      short_description: reqGr.getValue('short_description') || 'Service Request',
      time: reqGr.sys_updated_on.getDisplayValue(),
      table: 'sc_request',
      read: false // Session/client tracked
    });
  }

  // Calculate combined unread count
  data.totalCount = data.announcements.length + data.requests.length;

})();
